	local Functions = Resolve(Environment)
	local function Stage(Index, Message)
		if OnStage then OnStage(Index, Message) end
	end
	Stage(1, "Identifying your executor...")
	local Identify = Functions.identifyexecutor or Functions.getexecutorname
	if type(Identify) == "function" then
		local Success, Name = pcall(Identify)
		if Success and type(Name) == "string" and #Name > 0 then Result.Executor = string.sub(Name, 1, 60) end
	end
	Stage(2, "Checking required functions...")
	for _, Name in ipairs(Required) do
		if type(Functions[Name]) ~= "function" then Result.Missing[#Result.Missing + 1] = Name end
	end
	if not Compatibility.GetRequest(Environment) then Result.Missing[#Result.Missing + 1] = "request" end
	if #Result.Missing > 0 then return Result end

	Stage(3, "Verifying function behavior...")
	-- Runtime compilation keeps these disposable test functions outside obfuscator VMs.
	local Success = pcall(function()
		local Factory = assert(Functions.loadstring("return function(value) return value + 1 end, function(value) return value + 100 end"))
		local Target, Replacement = Factory()
		assert(type(Target) == "function" and type(Replacement) == "function")
		local Wrapped = Functions.newcclosure(Target)
		assert(type(Wrapped) == "function" and Wrapped(7) == 8)
		local References = { Target }
		local Original = Functions.hookfunction(Target, Replacement)
		local Hooked = References[1](7) == 107
		local Preserved = type(Original) == "function" and Original(7) == 8
		if Hooked and type(Original) == "function" then
			if type(Functions.restorefunction) == "function" then
				Functions.restorefunction(Target)
			else
