local RegistryUrl = "https://raw.githubusercontent.com/GodErste/Y-Core/main/games/index.lua"

--//Source
function Preflight.GetGame(Registry, PlaceId, ExpectedGame)
	local GameId = Registry.FindByPlaceId(PlaceId)
	if not GameId or (ExpectedGame and Registry.NormalizeGameId(ExpectedGame) ~= GameId) then return nil end
	return GameId
end

local function Fetch(Environment, Url, Cancelled, Failure)
	local Request = Compatibility.GetRequest(Environment)
	if type(Request) ~= "function" then return nil, "Connection failed" end
	local Active, Done, Body, Message = true, false, nil, "Connection failed"
	local Deadline = os.clock() + 6
	task.spawn(function()
		local Success, Response = pcall(Request, {
			Url = Url, Method = "GET", Headers = { ["Cache-Control"] = "no-cache" },
		})
		if not Active or Cancelled() then return end
		if Success and type(Response) == "table" then
			local Code = tonumber(Response.StatusCode)
			Message = Code == 429 and "Service busy" or Failure
			if Code == 200 and type(Response.Body) == "string" and #Response.Body <= 65536 then
				Body = Response.Body
			end
		end
		Done = true
	end)
	while not Done and os.clock() < Deadline and not Cancelled() do task.wait(0.05) end
	Active = false
	if Cancelled() then return nil, "cancelled" end
	if not Done then return nil, "Connection timed out" end
	return Body, Message
end

function Preflight.LoadRegistry(Environment, Cancelled)
	if not Compatibility.GetRequest(Environment) then return nil, "Executor not supported" end
	local Source, Message = Fetch(Environment, RegistryUrl, Cancelled, "Game list unavailable")
	if not Source then return nil, Message end
	local Success, Registry = pcall(function()
		local Chunk = assert(loadstring(Source, "@YHub.GameRegistry"))
		local Value = Chunk()
		assert(type(Value) == "table" and type(Value.Games) == "table")
		for _, Method in ipairs({ "FindByPlaceId", "NormalizeGameId", "GetGame" }) do
			assert(type(Value[Method]) == "function")
		end
		return Value
	end)
	if Success then return Registry end
	return nil, "Game list unavailable"
end

function Preflight.CheckWebsite(Environment, Cancelled)
	local Source, Message = Fetch(Environment, Endpoint, Cancelled, "Website unavailable")
	if not Source then return false, Message end
	local Parsed, Body = pcall(function() return game:GetService("HttpService"):JSONDecode(Source) end)
	local Available = Parsed and type(Body) == "table" and type(Body.games) == "table" and type(Body.sales) == "table"
	if Available then return true end
	return false, "Website unavailable"
end

return Preflight

