	if not Success then
		warn("[Y Hub] Startup interface could not open.")
		return nil
	end
	if not Screen:WaitForEntry() then return nil end
	Screen:SetStage(1, "Checking game")
	local Message
	Registry, Message = Preflight.LoadRegistry(getfenv(), function() return Screen.Destroyed end)
	if Screen.Destroyed then return nil end
	if not Registry then
		Screen:SetResult(false, Message)
		warn("[Y Hub] " .. Message)
		return nil
	end
	GameId = Preflight.GetGame(Registry, PlaceId, ExpectedGame)
	if not GameId then
		Screen:SetResult(false, "Game not supported")
		warn("[Y Hub] Game not supported: " .. tostring(PlaceId))
		return nil
	end
	local Finished = false
	task.delay(8, function()
		if not Finished and not Screen.Destroyed then
			Screen:SetResult(false, "Check timed out")
			Finished = true
		end
	end)
